INSERT INTO `crawler_answer` VALUES (1, '有能力高调如果高调了 那也是顺理成章 实事求是 如果低调了 那可能是格局大 或很成熟 或 对功名不屑一顾', '热心网友A', '2025-11-20 02:30:00.000000', 1, '2026-02-20 09:57:06.708155', 2);
INSERT INTO `crawler_answer` VALUES (2, '就是一种忌测吧，容易对他有印象，容易记住他。有什么困难会想到他。', '热心网友B', '2025-11-20 03:00:00.000000', 2, '2026-02-20 09:57:06.712707', 2);
INSERT INTO `crawler_answer` VALUES (3, '能，但可能性较低。Windows系统因用户多，是病毒木马的主要目标；macOS因权限管理严格、沙箱机制等防护措施，受攻击概率显著低于Windows。', '技术达人', '2025-11-20 06:00:00.000000', 1, '2026-02-20 09:57:06.714728', 3);
INSERT INTO `crawler_answer` VALUES (4, '因为当时的技术制造能力只有美苏比较强大啊，其他国家还不上美苏', '历史爱好者', '2025-11-20 07:30:00.000000', 1, '2026-02-20 09:57:06.716801', 4);
INSERT INTO `crawler_answer` VALUES (5, '第一代战机，第一代喷气发动机战机诞生于20世纪四十年代末，当时处于二战战后时期，欧洲强国忙于医治战争创伤，根本没有精力发展新战机，美苏率先突破了喷气发动机技术', '军事专家', '2025-11-20 08:00:00.000000', 2, '2026-02-20 09:57:06.718312', 4);
INSERT INTO `crawler_answer` VALUES (6, '简单的回答是：引力和斥力是相对的，而不是绝对的。', '物理老师', '2025-11-20 10:00:00.000000', 1, '2026-02-20 09:57:06.719873', 6);
INSERT INTO `crawler_answer` VALUES (7, '引力就是引力，斥力就是斥力。引力不会变成斥力，斥力不会变成引力。异性相吸，同性相斥是客观规律。', '科学爱好者', '2025-11-20 10:30:00.000000', 2, '2026-02-20 09:57:06.721575', 6);
INSERT INTO `crawler_answer` VALUES (8, '温和的姐姐（是外人）对温和的妹妹好，我觉得是姐姐总是喜欢妹妹的原因，姐姐总是一直给予妹无限的爱，护着她的弟弟妹妹。尽着一个姐姐的本分，传达着无限的爱意。让妹妹温暖。', '知心姐姐', '2025-11-19 01:00:00.000000', 1, '2026-02-20 09:57:06.724647', 7);
INSERT INTO `crawler_answer` VALUES (9, '通常情况下，\"佛山市\"和\"佛山\"指的是同一个地方，即中国广东省下辖的地级市，两者没有本质区别。\"佛山市\"是官方标准名称，\"佛山\"是简称，更常用于口语和媒体报道。', '本地通', '2025-11-19 04:00:00.000000', 1, '2026-02-20 09:57:06.726153', 8);
INSERT INTO `crawler_answer` VALUES (10, '天经地义。没有面包，人怎么活？选择\"面包\"而不选择\"爱情\"才是明智的、切合实际的。', '现实主义者', '2025-11-18 02:00:00.000000', 1, '2026-02-20 09:57:06.729126', 9);
INSERT INTO `crawler_answer` VALUES (11, '社会中宁愿选择\"面包\"也不选择\"爱情\"的人，给我的感觉是自私的人。', '理想主义者', '2025-11-18 02:30:00.000000', 2, '2026-02-20 09:57:06.730654', 9);
INSERT INTO `crawler_answer` VALUES (12, '不管是得军功还是牺牲，都令人尊敬崇拜。当然，能够活着回家还能立功，肯定是他们家里人都最希望看到的。', '退伍军人', '2025-11-18 06:00:00.000000', 1, '2026-02-20 09:57:06.733751', 10);
INSERT INTO `crawler_answer` VALUES (13, '我的感受是：人和人的命运就是如此不同，虽然他们都是我一手养大，我能决定他们的成长。然后就是释怀吧。', '父亲', '2025-11-18 06:30:00.000000', 2, '2026-02-20 09:57:06.735323', 10);
